// Status is a status code of ot_status other than OT_OK; a typed function
// returns it as its error.
type Status int32

// The status codes.
const (
	StatusInvalidArgument            Status = -1
	StatusUnsupportedVersion         Status = -2
	StatusOutOfMemory                Status = -3
	StatusWrongThread                Status = -4
	StatusInternalError              Status = -5
	StatusContextBusy                Status = -6
	StatusWrongContext               Status = -7
	StatusWrongKind                  Status = -8
	StatusStaleHandle                Status = -9
	StatusWrongSession               Status = -10
	StatusOutputBackpressure         Status = -11
	StatusSessionClosed              Status = -12
	StatusOutputBusy                 Status = -13
	StatusStaleOutput                Status = -14
	StatusOutputFailed               Status = -15
	StatusObjectLimit                Status = -16
	StatusRendererAttached           Status = -17
	StatusRendererNotAttached        Status = -18
	StatusInvalidPhase               Status = -19
	StatusControlPacketLimit         Status = -20
	StatusLeaseLimit                 Status = -21
	StatusLeaseBytesLimit            Status = -22
	StatusStaleLease                 Status = -23
	StatusUnsupportedResource        Status = -24
	StatusStaleFrame                 Status = -25
	StatusLayoutLimit                Status = -26
	StatusFrameBusy                  Status = -27
	StatusFrameRequestLimit          Status = -28
	StatusImageUnsupportedFormat     Status = -40
	StatusImageUnsupportedColorSpace Status = -41
	StatusImageMalformedData         Status = -42
	StatusImageDimensionLimit        Status = -43
	StatusImageMemoryLimit           Status = -44
	StatusImageOutputTooSmall        Status = -45
	StatusImageUnsupportedFeature    Status = -46
	StatusImageBusy                  Status = -47
	StatusVideoFailed                Status = -60
)

func (s Status) Error() string {
	switch s {
	case StatusInvalidArgument:
		return "opentui: OT_INVALID_ARGUMENT (-1)"
	case StatusUnsupportedVersion:
		return "opentui: OT_UNSUPPORTED_VERSION (-2)"
	case StatusOutOfMemory:
		return "opentui: OT_OUT_OF_MEMORY (-3)"
	case StatusWrongThread:
		return "opentui: OT_WRONG_THREAD (-4)"
	case StatusInternalError:
		return "opentui: OT_INTERNAL_ERROR (-5)"
	case StatusContextBusy:
		return "opentui: OT_CONTEXT_BUSY (-6)"
	case StatusWrongContext:
		return "opentui: OT_WRONG_CONTEXT (-7)"
	case StatusWrongKind:
		return "opentui: OT_WRONG_KIND (-8)"
	case StatusStaleHandle:
		return "opentui: OT_STALE_HANDLE (-9)"
	case StatusWrongSession:
		return "opentui: OT_WRONG_SESSION (-10)"
	case StatusOutputBackpressure:
		return "opentui: OT_OUTPUT_BACKPRESSURE (-11)"
	case StatusSessionClosed:
		return "opentui: OT_SESSION_CLOSED (-12)"
	case StatusOutputBusy:
		return "opentui: OT_OUTPUT_BUSY (-13)"
	case StatusStaleOutput:
		return "opentui: OT_STALE_OUTPUT (-14)"
	case StatusOutputFailed:
		return "opentui: OT_OUTPUT_FAILED (-15)"
	case StatusObjectLimit:
		return "opentui: OT_OBJECT_LIMIT (-16)"
	case StatusRendererAttached:
		return "opentui: OT_RENDERER_ATTACHED (-17)"
	case StatusRendererNotAttached:
		return "opentui: OT_RENDERER_NOT_ATTACHED (-18)"
	case StatusInvalidPhase:
		return "opentui: OT_INVALID_PHASE (-19)"
	case StatusControlPacketLimit:
		return "opentui: OT_CONTROL_PACKET_LIMIT (-20)"
	case StatusLeaseLimit:
		return "opentui: OT_LEASE_LIMIT (-21)"
	case StatusLeaseBytesLimit:
		return "opentui: OT_LEASE_BYTES_LIMIT (-22)"
	case StatusStaleLease:
		return "opentui: OT_STALE_LEASE (-23)"
	case StatusUnsupportedResource:
		return "opentui: OT_UNSUPPORTED_RESOURCE (-24)"
	case StatusStaleFrame:
		return "opentui: OT_STALE_FRAME (-25)"
	case StatusLayoutLimit:
		return "opentui: OT_LAYOUT_LIMIT (-26)"
	case StatusFrameBusy:
		return "opentui: OT_FRAME_BUSY (-27)"
	case StatusFrameRequestLimit:
		return "opentui: OT_FRAME_REQUEST_LIMIT (-28)"
	case StatusImageUnsupportedFormat:
		return "opentui: OT_IMAGE_UNSUPPORTED_FORMAT (-40)"
	case StatusImageUnsupportedColorSpace:
		return "opentui: OT_IMAGE_UNSUPPORTED_COLOR_SPACE (-41)"
	case StatusImageMalformedData:
		return "opentui: OT_IMAGE_MALFORMED_DATA (-42)"
	case StatusImageDimensionLimit:
		return "opentui: OT_IMAGE_DIMENSION_LIMIT (-43)"
	case StatusImageMemoryLimit:
		return "opentui: OT_IMAGE_MEMORY_LIMIT (-44)"
	case StatusImageOutputTooSmall:
		return "opentui: OT_IMAGE_OUTPUT_TOO_SMALL (-45)"
	case StatusImageUnsupportedFeature:
		return "opentui: OT_IMAGE_UNSUPPORTED_FEATURE (-46)"
	case StatusImageBusy:
		return "opentui: OT_IMAGE_BUSY (-47)"
	case StatusVideoFailed:
		return "opentui: OT_VIDEO_FAILED (-60)"
	}
	return "opentui: status " + strconv.FormatInt(int64(s), 10)
}

// statusError maps a status result to nil for OT_OK, else to its Status.
func statusError(s int32) error {
	if s == 0 {
		return nil
	}
	return Status(s)
}

// ABIMismatchError is the error of Load when ot_context_abi_version() is not OT_CONTEXT_ABI_VERSION.
type ABIMismatchError struct {
	Want, Got uint32
}

func (e *ABIMismatchError) Error() string {
	return fmt.Sprintf("opentui: the library's ABI version is %d, the binding's is %d", e.Got, e.Want)
}

var (
	// ErrNotLoaded is the error of a call before a successful Load.
	ErrNotLoaded = errors.New("opentui: Load has not succeeded")
	// ErrDestroyed is the error of a call on a nil or destroyed handle.
	ErrDestroyed = errors.New("opentui: the handle is nil or destroyed")
	// ErrTooLong is the error of a call with a slice longer than its C length holds.
	ErrTooLong = errors.New("opentui: a slice is longer than its C length holds")
)

var (
	loadMu sync.Mutex
	loaded atomic.Bool
)

func ready() error {
	if !loaded.Load() {
		return ErrNotLoaded
	}
	return nil
}

// sliceData is the address of the first element of s, or nil when s is empty.
func sliceData[T any](s []T) unsafe.Pointer {
	if len(s) == 0 {
		return nil
	}
	return unsafe.Pointer(unsafe.SliceData(s))
}

