// Load opens the library at path and binds every function of opentui.h.
// It looks up every symbol first (an error names a missing one), then calls
// ot_context_abi_version and returns *ABIMismatchError unless it returns OT_CONTEXT_ABI_VERSION (2),
// and only then registers the functions. A failed Load leaves the package
// unloaded: no C function was called but ot_context_abi_version, and every typed function
// returns ErrNotLoaded.
// Before it opens the library it makes the C pointer of each callback
// trampoline that has none yet (once per process); when purego has no
// callback slot left it returns *CallbackSlotsError and reaches no C code.
func Load(path string) error {
	loadMu.Lock()
	defer loadMu.Unlock()
	if loaded.Load() {
		return errors.New("opentui: Load: already loaded")
	}
	if err := cbMake(); err != nil {
		return err
	}
	lib, err := purego.Dlopen(path, purego.RTLD_NOW|purego.RTLD_LOCAL)
	if err != nil {
		return fmt.Errorf("opentui: Load %s: %w", path, err)
	}
	addrs := make([]uintptr, len(symbols))
	for i, s := range symbols {
		addr, err := purego.Dlsym(lib, s.name)
		if err != nil || addr == 0 {
			_ = purego.Dlclose(lib)
			return fmt.Errorf("opentui: Load %s: missing symbol %s (%v)", path, s.name, err)
		}
		addrs[i] = addr
	}
	var abi func() uint32
	purego.RegisterFunc(&abi, addrs[179])
	if got := abi(); got != 2 {
		_ = purego.Dlclose(lib)
		return &ABIMismatchError{Want: 2, Got: got}
	}
	for i, s := range symbols {
		purego.RegisterFunc(s.fn, addrs[i])
	}
	loaded.Store(true)
	return nil
}

// Context is a ot_context handle. ContextDestroy destroys it and sets it to nil; a later
// call on it returns ErrDestroyed. Thread affinity: owner.
type Context struct {
	p uintptr
	// t is the OS thread that created it (cbThread): a call that
	// changes a callback registration of a handle key checks it.
	t uintptr
}

